@Override
  public void storeInventory(IDeathStorage deathStorage) {
    PlayerEntity player = deathStorage.getPlayer();

    if (player != null) {
      PlayerInventory inventory = player.inventory;
      InventorySetting setting = deathStorage.getSettings().getInventorySettings();
      ListNBT list = new ListNBT();

      for (int i = 0; i < 9; i++) {
        InventoryHelper.process(player, inventory.getStackInSlot(i), i, list,
            i == inventory.currentItem ? InventorySection.MAINHAND : InventorySection.HOTBAR,
            setting);
      }

      for (int i = 9; i < 36; i++) {
        InventoryHelper
            .process(player, inventory.getStackInSlot(i), i, list, InventorySection.MAIN, setting);
      }
      InventoryHelper
          .process(player, inventory.getStackInSlot(36), 36, list, InventorySection.FEET, setting);
      InventoryHelper
          .process(player, inventory.getStackInSlot(37), 37, list, InventorySection.LEGS, setting);
      InventoryHelper
          .process(player, inventory.getStackInSlot(38), 38, list, InventorySection.CHEST, setting);
      InventoryHelper
          .process(player, inventory.getStackInSlot(39), 39, list, InventorySection.HEAD, setting);
      InventoryHelper
          .process(player, inventory.getStackInSlot(40), 40, list, InventorySection.OFFHAND,
              setting);
      deathStorage.addInventory("vanilla", list);
    }
  }

@Override
  public void retrieveInventory(IDeathStorage newStorage, IDeathStorage oldStorage) {
    PlayerEntity player = newStorage.getPlayer();
    PlayerEntity oldPlayer = oldStorage.getPlayer();

    if (player != null && oldPlayer != null) {
      ListNBT list = (ListNBT) oldStorage.getInventory("vanilla");

      if (list != null) {
        PlayerInventory inventory = player.inventory;

        for (int i = 0; i < list.size(); ++i) {
          CompoundNBT compoundnbt = list.getCompound(i);
          int slot = compoundnbt.getInt("Slot");
          ItemStack itemstack = ItemStack.read(compoundnbt);
          if (!itemstack.isEmpty()) {
            ItemStack existing = inventory.getStackInSlot(slot);

            if (existing.isEmpty()) {
              inventory.setInventorySlotContents(slot, itemstack);
            } else {
              ItemHandlerHelper.giveItemToPlayer(inventory.player, itemstack);
            }
          }
        }
      }
    }
  }

@Override
  public void storeInventory(IDeathStorage deathStorage) {
    PlayerEntity playerEntity = deathStorage.getPlayer();
    CAStacksBase stacks = CosArmorAPI.getCAStacks(playerEntity.getUniqueID());
    ListNBT list = new ListNBT();

    for (int i = 0; i < stacks.getSlots(); ++i) {
      ItemStack stack = stacks.getStackInSlot(i);
      if (!stack.isEmpty()) {
        InventoryHelper.process(playerEntity, stacks.getStackInSlot(i), i, list,
            InventorySection.COSMETIC_ARMOR, deathStorage.getSettings().getInventorySettings());
      }
    }
    deathStorage.addInventory("cosmeticarmorreworked", list);
  }

@Override
  public void retrieveInventory(IDeathStorage newStorage, IDeathStorage oldStorage) {
    PlayerEntity player = newStorage.getPlayer();
    PlayerEntity oldPlayer = oldStorage.getPlayer();

    if (player != null && oldPlayer != null) {
      ListNBT tagList = (ListNBT) oldStorage.getInventory("cosmeticarmorreworked");

      if (tagList != null) {
        CAStacksBase stacks = CosArmorAPI.getCAStacks(player.getUniqueID());

        for (int i = 0; i < tagList.size(); ++i) {
          CompoundNBT tag = tagList.getCompound(i);
          int slot = tag.getInt("Slot");
          ItemStack itemstack = ItemStack.read(tag);
          if (!itemstack.isEmpty()) {
            ItemStack existing = stacks.getStackInSlot(slot);

            if (existing.isEmpty()) {
              stacks.setStackInSlot(slot, itemstack);
            } else {
              ItemHandlerHelper.giveItemToPlayer(player, itemstack);
            }
          }
        }
      }
    }
  }

@Override
  public void storeInventory(IDeathStorage deathStorage) {
    PlayerEntity playerEntity = deathStorage.getPlayer();
    ListNBT list = new ListNBT();
    CuriosApi.getCuriosHelper().getCuriosHandler(playerEntity)
        .ifPresent(curioHandler -> curioHandler.getCurios().forEach((id, stackHandler) -> {
          ListNBT list1 = new ListNBT();
          ListNBT list2 = new ListNBT();

          for (int i = 0; i < stackHandler.getSlots(); i++) {
            InventoryHelper.process((PlayerEntity) curioHandler.getWearer(),
                stackHandler.getStacks().getStackInSlot(i), i, list1, InventorySection.CURIOS,
                deathStorage.getSettings().getInventorySettings());
            InventoryHelper.process((PlayerEntity) curioHandler.getWearer(),
                stackHandler.getCosmeticStacks().getStackInSlot(i), i, list2,
                InventorySection.CURIOS, deathStorage.getSettings().getInventorySettings());
          }
          CompoundNBT tag = new CompoundNBT();
          tag.putString("Identifier", id);
          tag.put("Stacks", list1);
          tag.put("CosmeticStacks", list2);
          ListNBT modifiers = new ListNBT();

          for (Map.Entry<UUID, AttributeModifier> entry : stackHandler.getModifiers().entrySet()) {
            CompoundNBT mod = new CompoundNBT();
            mod.put("Modifier", entry.getValue().write());
            modifiers.add(mod);
          }
          tag.put("Modifiers", modifiers);
          list.add(tag);
        }));
    deathStorage.addInventory("curios", list);
  }

@Override
  public void retrieveInventory(IDeathStorage newStorage, IDeathStorage oldStorage) {
    PlayerEntity player = newStorage.getPlayer();
    PlayerEntity oldPlayer = oldStorage.getPlayer();

    if (player != null && oldPlayer != null) {
      ListNBT list = (ListNBT) oldStorage.getInventory("curios");

      if (list != null) {
        CuriosApi.getCuriosHelper().getCuriosHandler(player).ifPresent(newHandler -> {

          for (int i = 0; i < list.size(); i++) {
            CompoundNBT tag = list.getCompound(i);
            String id = tag.getString("Identifier");
            newHandler.getStacksHandler(id).ifPresent(stacksHandler -> {
              ListNBT modifiers = tag.getList("Modifiers", NBT.TAG_COMPOUND);

              for (int i1 = 0; i1 < modifiers.size(); i1++) {
                CompoundNBT mod = modifiers.getCompound(i1);
                AttributeModifier attributeModifier =
                    AttributeModifier.read(mod.getCompound("Modifier"));
                stacksHandler.getCachedModifiers().add(attributeModifier);
                stacksHandler.addTransientModifier(attributeModifier);
              }
              stacksHandler.update();
              ListNBT stacks = tag.getList("Stacks", NBT.TAG_COMPOUND);

              for (int j = 0; j < stacks.size(); j++) {
                CompoundNBT compoundnbt = stacks.getCompound(j);
                int slot = compoundnbt.getInt("Slot");
                ItemStack itemstack = ItemStack.read(compoundnbt);

                if (!itemstack.isEmpty()) {
                  IDynamicStackHandler stackHandler = stacksHandler.getStacks();

                  if (stackHandler.getSlots() > slot &&
                      stackHandler.getStackInSlot(slot).isEmpty()) {
                    stacksHandler.getStacks().setStackInSlot(slot, itemstack);
                    CuriosApi.getCuriosHelper().getCurio(itemstack).ifPresent((curio) -> {
                      player.getAttributeManager()
                          .reapplyModifiers(curio.getAttributeModifiers(id));
                      curio.onEquip(id, slot, player);
                    });
                  } else {
                    ItemHandlerHelper.giveItemToPlayer(player, itemstack);
                  }
                }
              }
              ListNBT cosmeticStacks = tag.getList("CosmeticStacks", NBT.TAG_COMPOUND);

              for (int j = 0; j < cosmeticStacks.size(); j++) {
                CompoundNBT compoundnbt = stacks.getCompound(j);
                int slot = compoundnbt.getInt("Slot");
                ItemStack itemstack = ItemStack.read(compoundnbt);

                if (!itemstack.isEmpty()) {
                  IDynamicStackHandler stackHandler = stacksHandler.getCosmeticStacks();

                  if (stackHandler.getSlots() > slot &&
                      stackHandler.getStackInSlot(slot).isEmpty()) {
                    stacksHandler.getCosmeticStacks().setStackInSlot(slot, itemstack);
                  } else {
                    ItemHandlerHelper.giveItemToPlayer(player, itemstack);
                  }
                }
              }
            });
          }
        });
      }
    }
  }

@Override
  public void storeInventory(DeathStorageCapability.IDeathStorage deathStorage) {
    PlayerEntity playerEntity = deathStorage.getPlayer();

    if (ConfigData.customBeltSlotEnabled) {
      ItemStack belt = BeltFinder.findBelt(playerEntity).map(BeltFinder.BeltGetter::getBelt)
          .orElse(ItemStack.EMPTY);

      if (!belt.isEmpty()) {
        InventorySetting setting = deathStorage.getSettings().getInventorySettings();
        Enums.DropMode inventoryRule = InventoryHelper.getDropModeOverride(belt, setting);
        InventorySetting.SectionSettings defaultSettings =
            setting.getInventorySettings().get(Enums.InventorySection.DEFAULT);
        InventorySetting.SectionSettings sectionSettings = setting.getInventorySettings().get(
            Enums.InventorySection.TOOL_BELT);
        double keepChance =
            sectionSettings.keepChance >= 0 ? sectionSettings.keepChance :
                defaultSettings.keepChance;
        double destroyChance = sectionSettings.destroyChance >= 0 ? sectionSettings.destroyChance
            : defaultSettings.destroyChance;

        if (inventoryRule != null) {
          if (inventoryRule == Enums.DropMode.KEEP) {
            keepChance = 1.0D;
          } else if (inventoryRule == Enums.DropMode.DESTROY) {
            destroyChance = 1.0D;
          } else if (inventoryRule == Enums.DropMode.DROP) {
            keepChance = 0.0D;
          }
        }
        Random random = new Random();

        if (random.nextDouble() < keepChance) {
          deathStorage.addInventory("tool_belt", belt.serializeNBT());
          belt.shrink(1);
        } else if (random.nextDouble() < destroyChance) {
          belt.shrink(1);
        }
      }
    }
  }

@Override
  public void retrieveInventory(DeathStorageCapability.IDeathStorage newStorage,
                                DeathStorageCapability.IDeathStorage oldStorage) {
    PlayerEntity player = newStorage.getPlayer();
    PlayerEntity oldPlayer = oldStorage.getPlayer();

    if (player != null && oldPlayer != null) {
      CompoundNBT tag = (CompoundNBT) oldStorage.getInventory("tool_belt");

      if (tag != null) {
        ItemStack stack = ItemStack.read(tag);
        BeltFinder.setFinderSlotContents(player, BeltFinderBeltSlot.FINDER_ID, 0, stack);
      }
    }
  }

